/**
 * Built-in default WhatsApp message templates — one entry per reminder/share
 * message this app can send, across every business vertical. This is the
 * SOURCE OF TRUTH for default wording; MessageTemplate DB rows are sparse
 * overrides on top of these (see schema.prisma's MessageTemplate model doc
 * comment). An app update that improves a default here reaches every
 * business that never customized it.
 *
 * `tokens` lists the {{placeholder}} names each call site actually supplies
 * — shown in the Settings editor so an owner knows what's available and
 * won't reference a token that will never get substituted.
 *
 * `sendable: false` marks the one entry (RETAINER_INVOICE_DUE_3D) that's
 * actually an internal to-do note to staff, not a customer-facing message —
 * it has no phone/whatsappLink at its call site (retainer.service.ts).
 *
 * Business-name identity is deliberately NOT a token here: it's still
 * applied automatically by buildReminderWhatsAppLink's own `*Name*\n` prefix
 * (notification-queue.service.ts), unchanged by this feature. Two call
 * sites — HEARING_DUE_2D/7D and LIMITATION_DUE_30D/7D — used to ALSO thread
 * a manual "– firmName" signature into the body, which combined with that
 * automatic prefix put the business name in the message twice; this file's
 * defaults for those four drop the redundant manual signature (real bug
 * found+fixed 2026-09-22).
 */

export interface MessageTemplateDef {
  key: string
  vertical: string
  label: string
  /** English default — the universal fallback when no DB override exists and no `defaultBodyByLocale` entry covers the business's chosen reminder-message language. */
  defaultBody: string
  /** Per-language default wording, keyed by the same language codes as SUPPORTED_LANGUAGES (src/renderer/src/i18n/index.ts) minus 'en' (defaultBody above IS the English entry). Sparse is fine — any language missing here falls back to defaultBody. */
  defaultBodyByLocale?: Partial<Record<'hi' | 'mr' | 'gu' | 'kn' | 'ta' | 'te' | 'ml' | 'es' | 'fr' | 'pt' | 'ar' | 'id', string>>
  tokens: string[]
  sendable: boolean
}

